import{_ as r,l as n,o as e,c as s,v as t,p as i,x as l,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"风格控制","description":"","frontmatter":{"title":"风格控制","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/style-control.md","filePath":"llm/style-control.md","lastUpdated":1789023840000}'),c={name:"llm/style-control.md"};function h(A,a,m,_,u,f){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="风格控制" tabindex="-1">风格控制 <a class="header-anchor" href="#风格控制" aria-label="Permalink to &quot;风格控制&quot;">​</a></h1><div class="epigraph"><p>人与法官都爱列表和长文。不把风格从偏好里拆开，Elo 测的是排版，不是任务完成。</p><footer>—— 对照 Dubois 等 AlpacaEval 的长度控制；Arena 后续的风格协变量</footer></div><p><a href="/llm/elo-bt-rating">上一课</a>承认未控风格时强度含混淆。本课写控制。缺口是：截断再评、回归去长度、或强制短答，会改名次——那才说明原榜吃了风格。后课自我偏好是风格混淆的一种族谱特例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dubois 等人在 AlpacaEval 2.0 里展示：长度与胜率强相关，控制长度后许多「领先」缩小或翻转。Arena 加风格特征（长度、markdown、第一人称）进回归，得到「风格控制后的 Elo」。不控制时，RLHF 对冗长的奖励与评测仪器同构，优化器在刷仪器。</p><p>控制不是「风格无价值」。产品若真要健谈助手，应把健谈写成声明，用显式指标，而不是让它偷走「更正确」的名次。</p><p><span class="marginnote">简单截断会误伤需要长文的任务（代码补全、合同条款）。应按任务设长度预算，或在回归里把长度当协变量，而不是全局砍到 200 词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种互补。<strong>截断</strong>：两条回复裁到同一 token 预算再送法官或人。<strong>回归</strong>：在 BT 里加长度等协变量，报告受控 \\(s\\)。<strong>分层</strong>：按任务类型分别排名。AlpacaEval 的长度控制胜率是回归路线的一个实现，换数据集不要照抄系数。</p><p>与<a href="/llm/length-penalty-degeneration">长度惩罚</a>课对照：解码侧惩罚长度是生成策略；本课是评测侧不让长度决定名次。两边可以同时做，声明要分开。</p>',10)),(e(),i(E,null,{default:l(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%9B%9E%E5%A4%8D%22%5D%20--%3E%20LEN%5B%22%E9%95%BF%E5%BA%A6%20%2F%20markdown%20%E7%89%B9%E5%BE%81%22%5D%0A%20%20Y%20--%3E%20RAW%5B%22%E6%9C%AA%E6%8E%A7%20Elo%22%5D%0A%20%20LEN%20--%3E%20CTL%5B%22%E5%8D%8F%E5%8F%98%E9%87%8F%E6%88%96%E6%88%AA%E6%96%AD%22%5D%0A%20%20CTL%20--%3E%20ADJ%5B%22%E5%8F%97%E6%8E%A7%E5%BC%BA%E5%BA%A6%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>偏好模型（人脑或 LLM 法官）把「看起来费了工夫」当质量代理。长度是最廉价的工夫信号。控制相当于在估计里偏掉这条代理，逼迫剩余胜负来自内容。若控制后名次坍缩，说明原差距主要是代理；若名次稳定，说明内容差够大。两种结果都是信息，不要只发表稳定的那种。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>过度控制会把合法的详尽解释当作弊。应预先规定：哪些任务允许长、哪些任务风格应中性。下一课自我偏好：即使长度相同，法官仍可能偏爱「像自己」的句子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长度与列表是偏好评测的一等混淆，必须控制或分声明。</li><li>截断、协变量、按任务分层可并用，系数不可跨库照抄。</li><li>控制后名次翻转是有效发现，不是事故。</li><li>出处：Dubois 等 AlpacaEval 2.0；Arena 风格控制实践。</li></ul>',6))])}const B=r(c,[["render",h]]);export{b as __pageData,B as default};
